def sanitize_input(text: str) -> str:
    """Bemenet tisztítása injekciók ellen."""
    if not isinstance(text, str):
        return ""
    sanitized = re.sub(r'[<>"\'\\\x00-\x1f\x7f-\x9f]', "", text)
    sanitized = sanitized.strip()
    max_length = 10000
    if len(sanitized) > max_length:
        sanitized = sanitized[:max_length]
    return sanitized

def allowed_file(filename: str) -> bool:
    return "." in filename and filename.rsplit(".", 1)[1].lower() in ALLOWED_EXTENSIONS

def process_uploaded_file(file_path: str) -> str:
    """Egyszerű tartalomkinyerés ismert szöveges formátumokhoz."""
    try:
        lower = file_path.lower()
        if lower.endswith((".txt", ".md", ".csv")):
            with open(file_path, "r", encoding="utf-8", errors="replace") as f:
                return f.read()
        if lower.endswith(".json"):
            with open(file_path, "r", encoding="utf-8", errors="replace") as f:
                data = json.load(f)
            return json.dumps(data, indent=2, ensure_ascii=False)
        # Bináris formátumokhoz itt csak jelzést adunk
        if lower.endswith((".pdf", ".docx")):
            return "A fájl bináris formátumú (pdf/docx); jelenleg nincs beépített szövegkinyerés."
        return "Nem támogatott fájltípus a tartalomkinyeréshez."
    except Exception as e:
        logger.exception("File processing error")
        return f"Fájl feldolgozási hiba: {e}"

def ensure_event_loop():
    """Biztosít stabil eseményhurkot szálból hívva."""
    try:
        loop = asyncio.get_running_loop()
        return loop
    except RuntimeError:
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        return loop

def async_route(fn):
    """Flask-hez kompatibilis dekorátor aszinkron végrehajtáshoz."""
    @wraps(fn)
    def wrapper(*args, **kwargs):
        loop = ensure_event_loop()
        return loop.run_until_complete(fn(*args, **kwargs))
    return wrapper

