async def cerebras_generate(prompt: str, max_tokens: int = 2000) -> str:
    if not prompt:
        return ""
    # Demo mód
    if CEREBRAS_API_KEY == "demo-key":
        await asyncio.sleep(0.3)
        pl = prompt.lower()
        if any(t in pl for t in ["alphafold", "protein", "fehérje", "molekula", "folding", "structure"]):
            return (
                "**AlphaFold3 Elemzés (Demo)**\n\n"
                "A kérés fehérjeszerkezet-előrejelzés témájú, példaként diffúziós hajtogatás, "
                "ligandkölcsönhatás és konfidenciatérkép bemutatásával. "
                "Állíts be CEREBRAS_API_KEY értéket az éles generáláshoz."
            )
        return (
            "**JADED AI Válasz (Demo)**\n\n"
            "Részletes, markdown-os, magyar válasz; állíts be CEREBRAS_API_KEY-t az éles feldolgozáshoz."
        )

    # Éles mód
    timeout = aiohttp.ClientTimeout(total=60)
    connector = aiohttp.TCPConnector(limit=10, limit_per_host=5, ssl=False)
    async with aiohttp.ClientSession(timeout=timeout, connector=connector) as session:
        headers = {
            "Authorization": f"Bearer {CEREBRAS_API_KEY}",
            "Content-Type": "application/json",
            "User-Agent": "JADED-AI-Platform/2.5",
        }
        payload = {
            "model": "gpt-oss-120b",
            "messages": [
                {
                    "role": "system",
                    "content": (
                        "You are JADED AI, an advanced scientific research assistant. "
                        "Provide detailed, accurate responses in the user's language. "
                        "Use markdown formatting. Include context and citations when appropriate."
                    ),
                },
                {"role": "user", "content": prompt},
            ],
            "max_tokens": min(max_tokens, 65000),
            "temperature": 0.7,
            "top_p": 0.9,
            "stream": False,
        }
        try:
            async with session.post(
                "https://api.cerebras.ai/v1/chat/completions", json=payload, headers=headers
            ) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    return data.get("choices", [{}]).get("message", {}).get("content", "") or ""
                if resp.status == 429:
                    return "**Rate Limit Exceeded**\nKérlek próbáld újra később."
                if resp.status == 401:
                    return "**Hitelesítési hiba**\nÉrvénytelen API kulcs."
                text = await resp.text()
                return f"**API hiba ({resp.status})**\n{text[:500]}"
        except asyncio.TimeoutError:
            return "**Időtúllépés**\nA Cerebras kérés túllépte az időkorlátot."
        except aiohttp.ClientError as e:
            return f"**Kapcsolati hiba**\nNem sikerült kapcsolódni a Cerebras API-hoz: {e}"

async def exa_search(query: str, num_results: int = 5):
    if not query:
        return []
    # Demo mód
    if EXA_API_KEY == "demo-key":
        await asyncio.sleep(0.2)
        return [
            {
                "title": "AlphaFold3 overview",
                "url": "https://example.org/alphafold3",
                "text": "Áttekintés a legújabb fehérjehajtogatási módszerekről.",
                "published_date": "2024-05-08",
                "score": 0.95,
            }
        ]

    timeout = aiohttp.ClientTimeout(total=30)
    connector = aiohttp.TCPConnector(limit=5, ssl=False)
    async with aiohttp.ClientSession(timeout=timeout, connector=connector) as session:
        headers = {
            "x-api-key": EXA_API_KEY,
            "Content-Type": "application/json",
            "User-Agent": "JADED-AI-Platform/2.5",
        }
        payload = {
            "query": query,
            "num_results": num_results,
            "type": "neural",
            "use_autoprompt": True,
            "include_domains": [
                "arxiv.org",
                "pubmed.ncbi.nlm.nih.gov",
                "nature.com",
                "science.org",
                "cell.com",
                "academic.oup.com",
            ],
            "start_published_date": "2020-01-01",
            "text": True,
        }
        try:
            async with session.post("https://api.exa.ai/search", json=payload, headers=headers) as resp:
                if resp.status != 200:
                    return []
                data = await resp.json()
                results = data.get("results", []) or []
                enhanced = []
                for r in results:
                    enhanced.append(
                        {
                            "title": r.get("title", "Untitled"),
                            "url": r.get("url", ""),
                            "text": (r.get("text", "") or "")[:1000],
                            "published_date": r.get("published_date", "Unknown"),
                            "score": r.get("score", 0.0),
                            "domain": (r.get("url", "").split("/") if r.get("url") else "unknown"),
                        }
                    )
                return enhanced
        except Exception:
            logger.exception("Exa search failed")
            return []

