def run_julia_alphafold3(json_input: str, output_dir: str = "output", visualize: bool = False):
    """Julia pipeline futtatása biztonságosan, részletes hibakezeléssel."""
    try:
        os.makedirs(output_dir, exist_ok=True)

        with tempfile.NamedTemporaryFile(mode="w", suffix=".json", delete=False, encoding="utf-8") as f:
            f.write(json_input)
            input_file = f.name

        if not os.path.exists(JULIA_SCRIPT_PATH):
            return {
                "success": False,
                "error": f"Hiányzó Julia script: {JULIA_SCRIPT_PATH}",
            }

        cmd = [
            "julia",
            "--project=.",
            "--threads=auto",
            JULIA_SCRIPT_PATH,
            "--input",
            input_file,
            "--output",
            output_dir,
        ]
        if visualize:
            cmd.append("--visualize")

        env = os.environ.copy()
        cpu = os.cpu_count() or 2
        env["JULIA_NUM_THREADS"] = str(cpu)
        env["OMP_NUM_THREADS"] = str(cpu)

        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=600,
            env=env,
            cwd=os.getcwd(),
        )
        try:
            os.unlink(input_file)
        except Exception:
            pass

        if result.returncode != 0:
            return {
                "success": False,
                "error": result.stderr.strip() or "Ismeretlen hiba",
                "stdout": result.stdout,
                "debug_info": {
                    "return_code": result.returncode,
                    "command": " ".join(cmd),
                    "working_dir": os.getcwd(),
                },
            }

        output_files = []
        if os.path.exists(output_dir):
            for f in os.listdir(output_dir):
                if f.lower().endswith((".pdb", ".mmcif", ".json", ".jld2")):
                    output_files.append(f)

        return {
            "success": True,
            "stdout": result.stdout,
            "stderr": result.stderr,
            "output_dir": output_dir,
            "output_files": output_files,
            "prediction_quality": "High confidence" if "success" in result.stdout.lower() else "Standard",
        }
    except subprocess.TimeoutExpired:
        return {"success": False, "error": "Időtúllépés (10 perc)", "timeout": True}
    except FileNotFoundError:
        return {"success": False, "error": "A Julia nem található a PATH-ban."}
    except Exception as e:
        logger.exception("Julia futtatási hiba")
        return {"success": False, "error": str(e), "exception_type": type(e).__name__}

