@app.route("/api/alphafold3", methods=["POST"])
@async_route
async def alphafold3_prediction():
    try:
        data = request.get_json(silent=True) or {}
        sequence = sanitize_input(data.get("sequence", ""))
        name = sanitize_input(data.get("name", "Unknown"))
        visualize = bool(data.get("visualize", False))

        if not sequence or not re.fullmatch(r"[ACDEFGHIKLMNPQRSTVWY]+", sequence.upper()):
            return jsonify({"error": "Hiányzó vagy érvénytelen fehérjeszekvencia (A–Y, min. 10)."}), 400
        if len(sequence) < 10:
            return jsonify({"error": "Túl rövid szekvencia, min. 10 aminosav szükséges."}), 400

        alphafold_input = {
            "name": name,
            "sequences": [{"protein": {"id": "A", "sequence": sequence}}],
            "ligands": data.get("ligands", []),
            "nucleic_acids": data.get("nucleic_acids", []),
            "rng_seeds": ,
            "dialect": "alphafold3++",
            "version": 1,
            "metadata": {"experiment_id": f"EXP_{uuid.uuid4().hex[:8]}", "date": datetime.now().isoformat()},
        }

        output_dir = f"output_{uuid.uuid4().hex[:8]}"
        result = run_julia_alphafold3(json.dumps(alphafold_input), output_dir=output_dir, visualize=visualize)
        if not result.get("success"):
            return jsonify({"error": f"AlphaFold3 hiba: {result.get('error', 'ismeretlen')}"}), 500

        structure_info = {
            "name": name,
            "sequence_length": len(sequence),
            "prediction_completed": True,
            "output_directory": result["output_dir"],
            "files": result.get("output_files", []),
            "quality": result.get("prediction_quality", "Standard"),
            "logs": result.get("stdout", ""),
        }
        return jsonify(
            {
                "prediction": structure_info,
                "model_used": "JADED AlphaFold3 Julia v2.5",
                "processing_time": "A szekvenciahossztól függően változó",
                "confidence_score": "Post-processing során számítva",
            }
        )
    except Exception as e:
        logger.exception("alphafold3_prediction error")
        return jsonify({"error": f"Belső hiba: {e}"}), 500

