@app.route("/api/upload", methods=["POST"])
@async_route
async def upload_file():
    try:
        if "file" not in request.files:
            return jsonify({"error": "Hiányzó fájl."}), 400
        file = request.files["file"]
        if not file or not file.filename:
            return jsonify({"error": "Hiányzó fájlnév."}), 400
        if not allowed_file(file.filename):
            return jsonify({"error": "Érvénytelen fájltípus. Támogatott: txt, json, csv, md, pdf, docx"}), 400

        filename = secure_filename(f"{uuid.uuid4()}_{file.filename}")
        file_path = os.path.join(UPLOAD_FOLDER, filename)
        file.save(file_path)

        try:
            content = process_uploaded_file(file_path)
        finally:
            try:
                os.remove(file_path)
            except Exception:
                pass

        if re.search(r"[ACDEFGHIKLMNPQRSTVWY]{10,}", content.upper()):
            prompt = (
                "A dokumentum fehérjeszekvenciákat tartalmazhat. "
                "Elemezd a tartalmat és javasolj szerkezet-előrejelzési lehetőségeket:\n\n" + content
            )
        else:
            prompt = "Elemezd a dokumentum tartalmát és adj összefoglalót:\n\n" + content

        response = await cerebras_generate(prompt, max_tokens=1500)
        if not response:
            return jsonify({"error": "Nem sikerült elemezni a dokumentumot."}), 500

        return jsonify(
            {
                "response": response,
                "filename": file.filename,
                "model_used": "JADED Document Analyzer v2.5",
            }
        )
    except Exception as e:
        logger.exception("upload_file error")
        return jsonify({"error": f"Belső hiba: {e}"}), 500

