@socketio.on("message")
def handle_socket_message(data):
    try:
        query = sanitize_input((data or {}).get("query", (data or {}).get("message", "")))
        if not query:
            emit("response", {"error": "Hiányzó kérdés."})
            return

        def worker(q: str):
            loop = ensure_event_loop()
            try:
                if any(t in q.lower() for t in ["alphafold", "protein", "folding"]):
                    resp = (
                        "AlphaFold3 előrejelzés elérhető! Adj meg fehérjeszekvenciát, "
                        "vagy használd a webes felületet a teljes pipeline-hoz."
                    )
                else:
                    results = loop.run_until_complete(exa_search(q))
                    context = "\n".join([f"{r['title']}: {r['text']}" for r in results])
                    prompt = f"User query: {q}\nSearch results: {context}\nProvide a conversational response."
                    resp = loop.run_until_complete(cerebras_generate(prompt, max_tokens=1200)) or "Jelenleg nem elérhető válasz."
                emit("response", {"text": resp, "model": "JADED Real-time AI v2.5"})
            except Exception:
                logger.exception("Socket worker error")
                emit("response", {"error": "Feldolgozási hiba."})

        threading.Thread(target=worker, args=(query,), daemon=True).start()
    except Exception:
        logger.exception("Socket handler error")
        emit("response", {"error": "Belső hiba."})

